-- This suite uses synthetic Storage metadata only, and rolls back completely.
-- Actual bytes, signed URLs and browser identities are tested separately.
begin;
create temp table assertions(name text primary key,passed boolean not null);
grant select,insert on assertions to authenticated,anon,service_role;
create function pg_temp.ok(n text,b boolean) returns void language plpgsql as $$begin if b is distinct from true then raise exception 'FAILED: %',n;end if;insert into assertions values(n,true);end $$;
create function pg_temp.denied(s text,w text) returns boolean language plpgsql as $$begin execute s;return false;exception when others then return position(lower(w) in lower(sqlerrm))>0;end $$;
insert into auth.users(id,aud,role,email) values('bb000000-0000-4000-8000-000000000001','authenticated','authenticated','preseason-admin@example.invalid'),('bb000000-0000-4000-8000-000000000002','authenticated','authenticated','preseason-coach@example.invalid'),('bb000000-0000-4000-8000-000000000003','authenticated','authenticated','preseason-outsider@example.invalid');
select set_config('request.jwt.claims','{"sub":"bb000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
do $$declare l uuid;tid uuid;pid uuid;r jsonb;s jsonb;q jsonb;begin
 r:=public.league_command(null,'create_league','{"name":"Synthetic Preseason Test","season":"Upcoming 2026","cutoff":"2026-09-01"}');l:=(r->>'id')::uuid;perform set_config('test.preseason',l::text,true);
 s:=public.preseason_snapshot(l);perform pg_temp.ok('new ordinary season enforces preseason',(s#>>'{settings,enabled}')::boolean and s#>>'{settings,registration_status}'='draft');
 perform public.league_command(l,'invite_member','{"email":"preseason-coach@example.invalid","role":"coach"}');
 perform set_config('request.jwt.claims','{"sub":"bb000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
 perform pg_temp.ok('closed registration blocks new coach team',pg_temp.denied(format('select public.preseason_command(%L,''save_questionnaire'',''{"team_id":null,"name":"Fictional Team","data":{"experience":3},"submit":false}''::jsonb)',l),'registration is closed'));
 perform pg_temp.ok('coach cannot configure season',pg_temp.denied(format('select public.preseason_command(%L,''configure'',''{}'')',l),'reviewer required'));
 perform set_config('request.jwt.claims','{"sub":"bb000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
 perform public.preseason_command(l,'configure',jsonb_build_object('enabled',true,'season_name','Upcoming 2026','season_start','2026-11-07','cutoff_date','2026-09-01','registration_status','open','questionnaire_deadline',now()+interval '5 days','roster_deadline',now()+interval '6 days','verification_deadline',now()+interval '7 days','min_roster',1,'max_roster',12,'document_retention_days',14,'allowed_document_types',jsonb_build_array('birth_certificate','passport')));
 perform set_config('request.jwt.claims','{"sub":"bb000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
 r:=public.preseason_command(l,'save_questionnaire','{"team_id":null,"name":"Fictional Team","data":{"ageCategory":"U14","experience":3},"submit":false}');tid:=(r->>'team_id')::uuid;perform set_config('test.team',tid::text,true);
 s:=public.preseason_snapshot(l);perform pg_temp.ok('incomplete questionnaire draft persists',s#>>'{questionnaires,0,status}'='draft' and s#>>'{questionnaires,0,data,experience}'='3');
 perform pg_temp.ok('coach cannot approve placement',pg_temp.denied(format('select public.league_command(%L,''approve_team'',%L::jsonb)',l,jsonb_build_object('team_id',tid)),'Administrator required'));
 perform set_config('request.jwt.claims','{"sub":"bb000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
 perform pg_temp.ok('basic assessment is not comprehensive submission',pg_temp.denied(format('select public.league_command(%L,''approve_team'',%L::jsonb)',l,jsonb_build_object('team_id',tid)),'submitted comprehensive'));
 perform set_config('request.jwt.claims','{"sub":"bb000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
 q:='{"ageCategory":"U14","previousLeague":"Synthetic League","previousDivision":"Development","wins":8,"losses":4,"draws":0,"winningMargin":12,"losingMargin":8,"returningPercent":70,"competitivePlayers":5,"experience":3,"yearsTogether":2,"practicesPerWeek":2,"preferredTier":2,"coachConfidence":70,"notes":"Synthetic continuity evidence"}';
 r:=public.preseason_command(l,'save_questionnaire',jsonb_build_object('team_id',tid,'name','Fictional Team','data',q,'submit',true));
 perform pg_temp.ok('evidence recommendation is computed in database',r#>>'{recommendation,tier}'='1' and (r#>>'{recommendation,rating}')::int=1204 and (r#>>'{recommendation,confidence}')::numeric=.8);
 perform set_config('request.jwt.claims','{"sub":"bb000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
 perform pg_temp.ok('placement override needs reason',pg_temp.denied(format('select public.league_command(%L,''approve_team'',%L::jsonb)',l,jsonb_build_object('team_id',tid,'tier',2)),'override'));
 perform public.league_command(l,'approve_team',jsonb_build_object('team_id',tid,'tier',2,'override_reason','Administrator verified prior competition context'));
 perform pg_temp.ok('human override approved and audited',(public.preseason_snapshot(l)#>>'{readiness,0,placement_approved}')::boolean);
 perform set_config('request.jwt.claims','{"sub":"bb000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
 r:=public.league_command(l,'add_player',jsonb_build_object('team_id',tid,'display_name','Fictional Player','jersey','7','birth_date','2013-02-03','guardian_consent',true));pid:=(r->>'id')::uuid;perform set_config('test.player',pid::text,true);
 perform pg_temp.ok('coach cannot provide guardian consent',(public.preseason_snapshot(l)#>>'{players,0,guardian_consent}')::boolean=false);
 perform public.preseason_command(l,'submit_roster',jsonb_build_object('team_id',tid));
 perform pg_temp.ok('unverified roster blocks readiness',(public.preseason_snapshot(l)#>>'{readiness,0,eligible_for_scheduling}')::boolean=false);
 r:=public.preseason_command(l,'create_invitation',jsonb_build_object('player_id',pid,'token_hash',repeat('b',64),'email','guardian@example.invalid'));perform set_config('test.invitation',r->>'id',true);
 perform pg_temp.ok('invite hash never appears in coach snapshot',position(repeat('b',64) in public.preseason_snapshot(l)::text)=0);
 perform pg_temp.ok('raw guardian rows denied',pg_temp.denied('select * from public.guardian_invitations','permission denied'));
 perform pg_temp.ok('coach cannot inspect documents',pg_temp.denied(format('select public.preseason_command(%L,''open_document'',''{"document_id":"bb000000-0000-4000-8000-000000000099"}'')',l),'reviewer required'));
 perform pg_temp.ok('browser cannot forge Meta provider receipts',pg_temp.denied(format('select public.record_meta_evidence(%L,''{}'')',l),'permission denied'));
end $$;
reset role;
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
do $$declare s jsonb;r jsonb;begin
 s:=public.guardian_gateway(repeat('b',64),'status');perform pg_temp.ok('guardian capability shows only invited child',s#>>'{child,name}'='Fictional Player' and not(s::text like '%token_hash%') and not(s::text like '%storage_path%'));
 perform pg_temp.ok('invalid invitation uniformly denied',pg_temp.denied('select public.guardian_gateway(repeat(''c'',64),''status'')','Invitation unavailable'));
 perform pg_temp.ok('anonymous cannot read preseason roster',pg_temp.denied(format('select public.preseason_snapshot(%L)',current_setting('test.preseason')),'permission denied'));
 r:=public.guardian_gateway(repeat('b',64),'reserve_upload',jsonb_build_object('invitation_id',current_setting('test.invitation'),'document_type','birth_certificate','extension','png'));perform set_config('test.document',r->>'id',true);perform set_config('test.path',r->>'path',true);
 perform pg_temp.ok('guardian cannot bypass server file validation',pg_temp.denied(format('select public.finalize_age_upload(%L,%L,''{}'')',repeat('b',64),r->>'id'),'permission denied'));
 perform pg_temp.ok('guardian cannot reserve unacceptable proof',pg_temp.denied(format('select public.guardian_gateway(%L,''reserve_upload'',%L::jsonb)',repeat('b',64),jsonb_build_object('invitation_id',current_setting('test.invitation'),'document_type','school_report','extension','png')),'not accepted'));
end $$;
reset role;
insert into storage.objects(bucket_id,name) values('youth-documents',current_setting('test.path'));
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select public.finalize_age_upload(repeat('b',64),current_setting('test.document')::uuid,jsonb_build_object('sha256',repeat('d',64),'consent',true,'confirmed_details',true,'guardian_name','Fictional Guardian','relationship','parent'));
reset role;
select set_config('request.jwt.claims','{"sub":"bb000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
do $$declare l uuid:=current_setting('test.preseason')::uuid;did uuid:=current_setting('test.document')::uuid;s jsonb;begin
 s:=public.document_screening(l,did);
 perform pg_temp.ok('legacy proof screening is explicitly unable to assess',s->>'status'='unable_to_assess' and s->>'authenticity'='unverified');
 perform pg_temp.ok('screening never exposes image fingerprints',not(s ? 'perceptualHash') and (s->>'humanReviewRequired')::boolean);
 perform public.document_screening(l,did,'escalate','Synthetic original needs another authorized human inspection');
 perform pg_temp.ok('escalation retains mandatory pending human decision',public.preseason_snapshot(l)#>>'{players,0,verification_status}'='pending');
 perform pg_temp.ok('escalation is recorded in reviewer history',exists(select 1 from jsonb_array_elements(public.preseason_snapshot(l)->'reviews') rv where rv->>'decision'='escalated'));
 perform pg_temp.ok('basic age shortcut disabled',pg_temp.denied(format('select public.league_command(%L,''verify_player'',%L::jsonb)',l,jsonb_build_object('player_id',current_setting('test.player'))),'Document review is required'));
 perform pg_temp.ok('administrator must open original before approval',pg_temp.denied(format('select public.preseason_command(%L,''review_document'',%L::jsonb)',l,jsonb_build_object('document_id',did,'decision','approved','reason','Synthetic readable proof verified','document_checked',true,'duplicate_acknowledged',false)),'Open the private document'));
 perform public.preseason_command(l,'open_document',jsonb_build_object('document_id',did));
 perform public.preseason_command(l,'review_document',jsonb_build_object('document_id',did,'decision','resubmission','reason','Synthetic photo is cropped; provide a complete readable copy','document_checked',false,'duplicate_acknowledged',false));
 s:=public.preseason_snapshot(l);perform pg_temp.ok('resubmission is a real reviewer decision',s#>>'{players,0,verification_status}'='resubmission' and (s#>>'{readiness,0,eligible_for_scheduling}')::boolean=false);
 perform public.preseason_command(l,'review_document',jsonb_build_object('document_id',did,'decision','approved','reason','Synthetic proof was inspected and matches the declared details','document_checked',true,'duplicate_acknowledged',false));
 s:=public.preseason_snapshot(l);perform pg_temp.ok('human document approval unlocks completed team',(s#>>'{readiness,0,eligible_for_scheduling}')::boolean=true);
 perform pg_temp.ok('review retains reason and age policy',exists(select 1 from jsonb_array_elements(s->'reviews') r where r->>'decision'='approved' and r->>'age_at_cutoff'='13' and r->>'cutoff_date'='2026-09-01'));
 perform public.preseason_command(l,'configure_division',jsonb_build_object('name','U14 · Competitive','age_category','U14','tier',2,'min_age',0,'max_age',12));
 perform pg_temp.ok('changed age rule invalidates prior approval',(public.preseason_snapshot(l)#>>'{readiness,0,eligible_for_scheduling}')::boolean=false);
 perform pg_temp.ok('new age rule cannot be bypassed by old proof',pg_temp.denied(format('select public.preseason_command(%L,''review_document'',%L::jsonb)',l,jsonb_build_object('document_id',did,'decision','approved','reason','Old approval does not bypass changed age policy','document_checked',true,'duplicate_acknowledged',false)),'outside the configured'));
 perform public.preseason_command(l,'configure_division',jsonb_build_object('name','U14 · Competitive','age_category','U14','tier',2,'min_age',0,'max_age',13));
 perform public.preseason_command(l,'review_document',jsonb_build_object('document_id',did,'decision','approved','reason','Re-reviewed synthetic proof under restored age eligibility policy','document_checked',true,'duplicate_acknowledged',false));
 perform set_config('request.jwt.claims','{"sub":"bb000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
 perform pg_temp.ok('outsider cannot inspect private preseason',pg_temp.denied(format('select public.preseason_snapshot(%L)',l),'access denied'));
 perform pg_temp.ok('outsider cannot inspect derived screening',pg_temp.denied(format('select public.document_screening(%L,%L)',l,did),'reviewer required'));
 perform pg_temp.ok('outsider cannot obtain private document path',pg_temp.denied(format('select public.preseason_command(%L,''open_document'',%L::jsonb)',l,jsonb_build_object('document_id',did)),'access denied'));
end $$;
reset role;
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select public.guardian_gateway(repeat('b',64),'withdraw_consent',jsonb_build_object('invitation_id',current_setting('test.invitation')));
reset role;
select set_config('request.jwt.claims','{"sub":"bb000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select pg_temp.ok('guardian withdrawal immediately blocks scheduling',(public.preseason_snapshot(current_setting('test.preseason')::uuid)#>>'{readiness,0,eligible_for_scheduling}')::boolean=false);
select public.preseason_command(current_setting('test.preseason')::uuid,'revoke_invitation',jsonb_build_object('invitation_id',current_setting('test.invitation')));
reset role;
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select pg_temp.ok('revocation invalidates existing guardian sessions',pg_temp.denied('select public.guardian_gateway(repeat(''b'',64),''status'')','Invitation unavailable'));
select pg_temp.ok('no public document bytes',(select count(*)=0 from storage.objects where bucket_id='youth-documents'));
reset role;
select jsonb_build_object('passed',count(*),'tests',jsonb_agg(name order by name)) as test_results from assertions;
rollback;
